    46	export class ToolRegistry {
    47	  private readonly tools = new Map<string, StoredTool>();
    48	  private readonly ajv = new AjvConstructor({
    49	    strict: false,
    50	    validateFormats: false,
    51	    coerceTypes: false,
    52	    useDefaults: false,
    53	  });
    54	  private readonly compiledSchemas = new WeakMap<Record<string, unknown>, ValidateFunction>();
    55	
    56	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    57	    return typeof source === 'function' ? source() : source;
    58	  }
