    61	    const resolved = this.resolveDefinition(definition);
    62	    let validator: ValidateFunction | undefined;
    63	    if (typeof definition !== 'function') {
    64	      validator = this.ajv.compile(resolved.inputSchema) as ValidateFunction;
    65	    }
    66	    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
    67	  }
